  var bookMatch = url.match(/\/book\/(\d+)/);
  if (bookMatch) {
    var bookId = bookMatch[1];
    var prefix = bookId.substring(0, 3);
    return '/' + prefix + '/' + bookId + '/';
  }
  try {
    var doc = org.jsoup.Jsoup.parse(result);
    var a = doc.selectFirst('a[href*="/book/"]');
    if (a) {
      var href = String(a.attr('href'));
      var m = href.match(/\/book\/(\d+)/);
      if (m) {
        var bId = m[1];
        var p = bId.substring(0, 3);
        return '/' + p + '/' + bId + '/';
      }
    }
  } catch (e) {}
  return '';
})();

